#!/usr/bin/env python3
# Onyx: the named character references table of the HTML standard (all 2231 names, from
# https://html.spec.whatwg.org/entities.json, a copy beside this script) written as a sorted C
# table for the tokeniser: src/tokeniser/onyx_entities.inc. Run from third_party/libhubbub:
#   python3 build/make-onyx-entities.py
import json, os
here = os.path.dirname(os.path.abspath(__file__))
d = json.load(open(os.path.join(here, 'entities.json')))
names = sorted((k[1:], v['codepoints']) for k, v in d.items())
parts, rows, off = [], [], 0
for n, cps in names:
    b = n.encode('ascii')
    rows.append((off, len(b), cps[0], cps[1] if len(cps) > 1 else 0))
    parts.append(n)
    off += len(b)
legacy = max(len(n) for n, _ in names if not n.endswith(';'))
out = open(os.path.join(here, '..', 'src', 'tokeniser', 'onyx_entities.inc'), 'w')
out.write('/* Onyx: generated by build/make-onyx-entities.py from the HTML standard\'s entities.json:\n'
          ' * %d named character references, sorted by name (without the "&"). */\n' % len(names))
out.write('#define ONYX_ENTITY_COUNT %d\n#define ONYX_ENTITY_MAXLEN %d\n#define ONYX_ENTITY_LEGACY_MAXLEN %d\n'
          % (len(names), max(len(n) for n, _ in names), legacy))
out.write('static const char onyx_entity_names[] =\n')
s = ''.join(parts)
for i in range(0, len(s), 72):
    out.write('\t"%s"\n' % s[i:i + 72])
out.write('\t;\n')
out.write('static const struct onyx_entity { uint16_t off; uint8_t len; uint16_t cp2; uint32_t cp1; } onyx_entities[] = {\n')
for off, ln, c1, c2 in rows:
    out.write('\t{ %d, %d, 0x%x, 0x%x },\n' % (off, ln, c2, c1))
out.write('};\n')
